        ys = [torch.tensor(y, dtype=torch.float64) for y in state["Y"]]
        if any(x.shape != (self._dim,) or not torch.isfinite(x).all()
               or (x < 0).any() or (x > 1).any() for x in xs):
            raise ValueError("Invalid checkpoint coordinates")
